import { unzipSync } from "fflate";
// Generates the Industrial Foregoing sprite registry + CSS from two pinned
// upstream commits (Industrial Foregoing for the machine atlas, Titanium for
// the shared machine background). Run:
//   pnpm --filter @tennantite/textures sync:industrialforegoing-sprites
//
// The commits are pinned so the generated files are reproducible. `--check`
// re-renders and compares against the committed files.
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const IF_COMMIT = "ce2852db4b34af3ab1b9637cff0b327d4bb561d5";
const IF_ZIP = `https://codeload.github.com/InnovativeOnlineIndustries/Industrial-Foregoing/zip/${IF_COMMIT}`;
const IF_ASSET_ROOT = "src/main/resources/assets/industrialforegoing/textures/gui/";

const TI_COMMIT = "f8f0461458a4a3a54aa0239c9243a7716b7be436";
const TI_ZIP = `https://codeload.github.com/InnovativeOnlineIndustries/Titanium/zip/${TI_COMMIT}`;
const TI_ASSET_ROOT = "src/main/resources/assets/titanium/textures/gui/";

const ROOT = fileURLToPath(new URL("../", import.meta.url));
const OUT_TS = `${ROOT}src/industrialforegoing-sprites.generated.ts`;
const OUT_CSS = `${ROOT}css/industrialforegoing-sprites.generated.css`;
const OUT_TEXTURES = `${ROOT}css/industrialforegoing-textures.css`;

const check = process.argv.includes("--check");

const SOURCES = [
  { archive: "if", file: "machines.png", name: "machines" },
  { archive: "if", file: "machines_extra.png", name: "machines_extra" },
  { archive: "if", file: "donate.png", name: "donate" },
  { archive: "ti", file: "background.png", name: "titanium_background" },
  { archive: "ti", file: "background_alt.png", name: "titanium_background_alt" },
];

function cssVar(name) {
  return `--mc-if-${name.toLowerCase().replaceAll(/[^a-z0-9]+/g, "-")}`;
}

async function download(url) {
  let lastError;
  for (let attempt = 1; attempt <= 4; attempt += 1) {
    try {
      const response = await fetch(url);
      if (!response.ok) {
        throw new Error(`HTTP ${response.status} ${response.statusText}`);
      }
      return new Uint8Array(await response.arrayBuffer());
    }
    catch (error) {
      lastError = error;
      if (attempt < 4) {
        await new Promise(resolve => setTimeout(resolve, attempt * 500));
      }
    }
  }
  throw new Error(`cannot download ${url}`, { cause: lastError });
}

function pngSize(bytes) {
  const view = new DataView(bytes.buffer, bytes.byteOffset);
  return { height: view.getUint32(20), width: view.getUint32(16) };
}

function sourceName(fullName, assetRoot, file) {
  const marker = fullName.indexOf(assetRoot);
  return marker !== -1 && (fullName.slice(marker + assetRoot.length) === file);
}

const [ifZip, tiZip] = await Promise.all([download(IF_ZIP), download(TI_ZIP)]);
const archives = {
  if: {
    files: unzipSync(ifZip, {
      filter: file => file.name.endsWith(".png") && file.name.includes(IF_ASSET_ROOT),
    }),
    root: IF_ASSET_ROOT,
  },
  ti: {
    files: unzipSync(tiZip, {
      filter: file => file.name.endsWith(".png") && file.name.includes(TI_ASSET_ROOT),
    }),
    root: TI_ASSET_ROOT,
  },
};

const entries = SOURCES.map(({ archive, file, name }) => {
  const { files, root } = archives[archive];
  const match = Object.entries(files).find(([fullName]) => sourceName(fullName, root, file));
  if (!match) {
    throw new Error(`missing ${file} under ${root}`);
  }
  const bytes = match[1];
  const { height, width } = pngSize(bytes);
  return {
    base64: Buffer.from(bytes).toString("base64"),
    cssVar: cssVar(name),
    height,
    name,
    sha256: createHash("sha256").update(bytes).digest("hex"),
    width,
  };
});

if (entries.length !== 5) {
  throw new Error(`expected 5 Industrial Foregoing sprites, got ${entries.length}`);
}

const metaLines = entries.map(entry => `  ${JSON.stringify(entry.name)}: {
    cssVar: ${JSON.stringify(entry.cssVar)},
    height: ${entry.height},
    sha256: ${JSON.stringify(entry.sha256)},
    width: ${entry.width},
  },`);

const ts = `// Generated by scripts/sync-industrialforegoing-sprites.mjs — DO NOT EDIT.
// Sources: Industrial Foregoing ${IF_COMMIT} (MIT) and
// Titanium ${TI_COMMIT} (LGPL-3.0).
// See LICENSE-ASSETS.md.
// Regenerate: pnpm --filter @tennantite/textures sync:industrialforegoing-sprites

export interface IndustrialForegoingSpriteMeta {
  cssVar: string;
  height: number;
  sha256: string;
  width: number;
}

export const industrialForegoingSpriteMeta = {
${metaLines.join("\n")}
} as const;

export type IndustrialForegoingSpriteName = keyof typeof industrialForegoingSpriteMeta;
`;

const cssLines = entries.map(
  entry => `  ${entry.cssVar}: url("data:image/png;base64,${entry.base64}");`,
);

const css = `/*
 * Generated by scripts/sync-industrialforegoing-sprites.mjs — DO NOT EDIT.
 * Sources: Industrial Foregoing ${IF_COMMIT} (MIT) and
 * Titanium ${TI_COMMIT} (LGPL-3.0).
 * See LICENSE-ASSETS.md.
 */
:root {
${cssLines.join("\n")}
}
`;

const textures = `/*
 * Industrial Foregoing sprite layer. Import after the vanilla sprite CSS.
 * Generated data URIs live in industrialforegoing-sprites.generated.css.
 */
@import "./industrialforegoing-sprites.generated.css";

.mc-if-sprite {
  background-repeat: no-repeat;
  image-rendering: pixelated;
}
`;

if (check) {
  let isStale = false;
  for (const [file, expected] of [
    [OUT_TS, ts],
    [OUT_CSS, css],
    [OUT_TEXTURES, textures],
  ]) {
    let actual = "";
    try {
      actual = readFileSync(file, "utf8");
    }
    catch {
      isStale = true;
      continue;
    }
    if (actual === expected) {
      continue;
    }
    isStale = true;
    console.error(`out of date: ${file}`);
  }
  if (isStale) {
    process.exit(1);
  }
  console.log(`Industrial Foregoing sprites up to date (${entries.length})`);
}
else {
  writeFileSync(OUT_TS, ts);
  writeFileSync(OUT_CSS, css);
  writeFileSync(OUT_TEXTURES, textures);
  console.log(`wrote ${entries.length} Industrial Foregoing sprites`);
}
